=IFERROR(
  IF(
    COUNTA(
      FILTER(
        {'상업멀티'!B4:B108; '상업멀티'!B344:B352; '상업멀티'!B353:B415},
        N({'상업멀티'!F4:F108; '상업멀티'!F344:F352; '상업멀티'!F353:F415}) >= 1
      )
    ) = 0,
    "-",
    LET(
      raw,
        FLATTEN(
          ARRAYFORMULA(
            SPLIT(
              REPT(
                {'상업멀티'!B4:B108; '상업멀티'!B344:B352; '상업멀티'!B353:B415} & ",",
                N({'상업멀티'!F4:F108; '상업멀티'!F344:F352; '상업멀티'!F353:F415})
              ),
              ","
            )
          )
        ),
      lst, FILTER(raw, raw <> ""),
      n,   ROWS(lst),
      MAKEARRAY(
        1,
        n * 2 - 1,
        LAMBDA(r, c, IF(ISEVEN(c), "", INDEX(lst, (c + 1) / 2)))
      )
    )
  ),
  ""
)

